import { createFileRoute } from '@tanstack/react-router'
import { useCallback, useEffect, useMemo, useState } from 'react'
import type { FormEvent, ReactNode } from 'react'
import type { LucideIcon } from 'lucide-react'
import { Activity, ArrowDownLeft, ArrowUpRight, BarChart3, CalendarDays, Check, CreditCard, Download, FileSpreadsheet, Filter, Goal, Landmark, LayoutDashboard, LogOut, Moon, Plus, Search, Smartphone, Sun, Trash2, TrendingUp, Wallet, X } from 'lucide-react'
import { Area, AreaChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { jsPDF } from 'jspdf'
import * as XLSX from 'xlsx'
import { toast } from 'sonner'
import { blink } from '@/blink/client'
import { BlinkClientBoundary } from '@/components/BlinkClientBoundary'
import type { FinanceAccountsRow, FinanceBudgetsRow, FinanceCardsRow, FinanceCategoriesRow, FinanceGoalsRow, FinanceTransactionsRow } from '@/lib/db-types'

const txDb = blink.db.table<FinanceTransactionsRow>('finance_transactions')
const accountDb = blink.db.table<FinanceAccountsRow>('finance_accounts')
const cardDb = blink.db.table<FinanceCardsRow>('finance_cards')
const categoryDb = blink.db.table<FinanceCategoriesRow>('finance_categories')
const budgetDb = blink.db.table<FinanceBudgetsRow>('finance_budgets')
const goalDb = blink.db.table<FinanceGoalsRow>('finance_goals')
type Page = 'overview' | 'transactions' | 'accounts' | 'planning' | 'reports'
type ModalKind = 'transaction' | 'account' | 'card' | 'budget' | 'goal' | 'category' | 'contribution'
type User = { id: string; email?: string | null; displayName?: string | null }
type InstallPrompt = Event & { prompt: () => Promise<void>; userChoice: Promise<{ outcome: string }> }
const nav: { id: Page; label: string; icon: LucideIcon }[] = [
  { id: 'overview', label: 'Início', icon: LayoutDashboard },
  { id: 'transactions', label: 'Lançamentos', icon: Activity },
  { id: 'accounts', label: 'Contas', icon: Wallet },
  { id: 'planning', label: 'Planejamento', icon: Goal },
  { id: 'reports', label: 'Relatórios', icon: BarChart3 },
]
const input = 'mt-1.5 h-11 w-full rounded-xl border border-input bg-background px-3.5 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15'
const label = 'block text-xs font-semibold text-muted-foreground'

export const Route = createFileRoute('/app/')({
  head: () => ({ meta: [{ title: 'FinanceX — sua vida financeira em equilíbrio' }, { name: 'description', content: 'Organize receitas, despesas, cartões, metas e orçamentos em um só lugar.' }], links: [{ rel: 'manifest', href: '/manifest.webmanifest' }] }),
  component: FinancePage,
})

function FinancePage() { return <BlinkClientBoundary fallback={<Loading />}><FinanceApp /></BlinkClientBoundary> }

function FinanceApp() {
  const [user, setUser] = useState<User | null>(null)
  const [authLoading, setAuthLoading] = useState(true)
  const [busy, setBusy] = useState(false)
  const [tx, setTx] = useState<FinanceTransactionsRow[]>([])
  const [accounts, setAccounts] = useState<FinanceAccountsRow[]>([])
  const [cards, setCards] = useState<FinanceCardsRow[]>([])
  const [categories, setCategories] = useState<FinanceCategoriesRow[]>([])
  const [budgets, setBudgets] = useState<FinanceBudgetsRow[]>([])
  const [goals, setGoals] = useState<FinanceGoalsRow[]>([])
  const [page, setPage] = useState<Page>('overview')
  const [modal, setModal] = useState<ModalKind | null>(null)
  const [goalId, setGoalId] = useState('')
  const [search, setSearch] = useState('')
  const [kindFilter, setKindFilter] = useState('all')
  const [categoryFilter, setCategoryFilter] = useState('all')
  const [dateFrom, setDateFrom] = useState('')
  const [dateTo, setDateTo] = useState('')
  const [dark, setDark] = useState(() => {
    if (typeof window === 'undefined') return false
    try {
      const theme = localStorage.getItem('financex-theme')
      return theme ? theme === 'dark' : document.documentElement.classList.contains('dark')
    } catch { return false }
  })
  const [install, setInstall] = useState<InstallPrompt | null>(null)
  const [showInstallHelp, setShowInstallHelp] = useState(false)

  useEffect(() => blink.auth.onAuthStateChanged((state) => {
    setUser(state.user as User | null)
    if (!state.isLoading) setAuthLoading(false)
  }), [])

  useEffect(() => {
    if ('serviceWorker' in navigator) void navigator.serviceWorker.register('/sw.js').catch(() => undefined)
    const captureInstall = (event: Event) => { event.preventDefault(); setInstall(event as InstallPrompt) }
    window.addEventListener('beforeinstallprompt', captureInstall)
    return () => window.removeEventListener('beforeinstallprompt', captureInstall)
  }, [])

  useEffect(() => { document.documentElement.classList.toggle('dark', dark) }, [dark])

  const refresh = useCallback(async (userId: string) => {
    setBusy(true)
    try {
      let userCategories = await categoryDb.list({ where: { userId }, orderBy: { name: 'asc' } })
      if (!userCategories.length) {
        await categoryDb.createMany([
          { userId, name: 'Moradia', transactionType: 'expense', color: '#6f9e8a' },
          { userId, name: 'Alimentação', transactionType: 'expense', color: '#c89b5f' },
          { userId, name: 'Transporte', transactionType: 'expense', color: '#7495aa' },
          { userId, name: 'Saúde', transactionType: 'expense', color: '#a97774' },
          { userId, name: 'Lazer', transactionType: 'expense', color: '#aa8d72' },
          { userId, name: 'Salário', transactionType: 'income', color: '#5b9c83' },
          { userId, name: 'Freelance', transactionType: 'income', color: '#668eb0' },
        ])
        userCategories = await categoryDb.list({ where: { userId }, orderBy: { name: 'asc' } })
      }
      const [transactions, nextAccounts, nextCards, nextBudgets, nextGoals] = await Promise.all([
        txDb.list({ where: { userId }, orderBy: { transactionDate: 'desc' }, limit: 1000 }),
        accountDb.list({ where: { userId }, orderBy: { createdAt: 'asc' } }),
        cardDb.list({ where: { userId }, orderBy: { createdAt: 'asc' } }),
        budgetDb.list({ where: { userId }, orderBy: { month: 'desc' } }),
        goalDb.list({ where: { userId }, orderBy: { createdAt: 'desc' } }),
      ])
      setTx(transactions); setAccounts(nextAccounts); setCards(nextCards); setCategories(userCategories); setBudgets(nextBudgets); setGoals(nextGoals)
    } catch (error) { toast.error(error instanceof Error ? error.message : 'Não foi possível carregar seus dados.') }
    finally { setBusy(false) }
  }, [])

  useEffect(() => {
    if (!user) return
    const timer = window.setTimeout(() => { void refresh(user.id) }, 0)
    return () => window.clearTimeout(timer)
  }, [user, refresh])
  const month = monthKey()
  const monthTx = useMemo(() => tx.filter((row) => row.transactionDate.slice(0, 7) === month), [tx, month])
  const income = monthTx.filter((row) => row.transactionType === 'income').reduce((sum, row) => sum + Number(row.amount), 0)
  const expenses = monthTx.filter((row) => row.transactionType === 'expense').reduce((sum, row) => sum + Number(row.amount), 0)
  const balance = accounts.reduce((total, account) => total + Number(account.initialBalance) + tx.filter((row) => row.accountId === account.id).reduce((sum, row) => sum + (row.transactionType === 'income' ? 1 : -1) * Number(row.amount), 0), 0)
  const chart = useMemo(() => Array.from({ length: 6 }, (_, i) => {
    const date = new Date(); date.setDate(1); date.setMonth(date.getMonth() - 5 + i)
    const rows = tx.filter((row) => row.transactionDate.slice(0, 7) === monthKey(date))
    return { name: date.toLocaleDateString('pt-BR', { month: 'short' }).replace('.', ''), receitas: rows.filter((r) => r.transactionType === 'income').reduce((sum, r) => sum + Number(r.amount), 0), despesas: rows.filter((r) => r.transactionType === 'expense').reduce((sum, r) => sum + Number(r.amount), 0) }
  }), [tx])
  const breakdown = categories.filter((category) => category.transactionType === 'expense').map((category) => ({ name: category.name, value: monthTx.filter((row) => row.transactionType === 'expense' && row.categoryId === category.id).reduce((sum, row) => sum + Number(row.amount), 0), color: category.color })).filter((item) => item.value > 0).sort((a, b) => b.value - a.value)
  const filtered = tx.filter((row) => {
    const category = categories.find((item) => item.id === row.categoryId)?.name ?? ''
    return `${row.title} ${row.note ?? ''} ${category}`.toLowerCase().includes(search.toLowerCase()) && (kindFilter === 'all' || row.transactionType === kindFilter) && (categoryFilter === 'all' || row.categoryId === categoryFilter) && (!dateFrom || row.transactionDate >= dateFrom) && (!dateTo || row.transactionDate <= dateTo)
  })

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (!user || !modal) return
    const form = new FormData(event.currentTarget)
    const val = (key: string) => String(form.get(key) ?? '').trim()
    try {
      if (modal === 'transaction') {
        const amount = Number(val('amount'))
        const count = Math.min(24, Math.max(1, Number(val('installments')) || 1))
        if (!val('title') || amount <= 0) throw new Error('Informe a descrição e um valor maior que zero.')
        const date = new Date(`${val('date')}T12:00:00`)
        const group = count > 1 ? crypto.randomUUID() : null
        await txDb.createMany(Array.from({ length: count }, (_, i) => ({ userId: user.id, title: count > 1 ? `${val('title')} · ${i + 1}/${count}` : val('title'), amount: Math.round(amount / count * 100) / 100, transactionType: val('type'), categoryId: val('category') || null, accountId: val('account') || null, cardId: val('card') || null, transactionDate: dateKey(addMonths(date, i)), note: val('note') || null, paymentMethod: val('payment') || null, installmentGroup: group, installmentIndex: i + 1, installmentCount: count })))
        toast.success(count > 1 ? `${count} parcelas registradas.` : 'Movimentação registrada.')
      } else if (modal === 'account') {
        if (!val('name')) throw new Error('Informe o nome da conta.')
        await accountDb.create({ userId: user.id, name: val('name'), accountType: val('accountType'), initialBalance: Number(val('balance')) || 0 }); toast.success('Conta adicionada.')
      } else if (modal === 'card') {
        if (!val('name') || !val('lastFour')) throw new Error('Informe o nome e os quatro últimos dígitos do cartão.')
        await cardDb.create({ userId: user.id, name: val('name'), lastFour: val('lastFour').slice(-4), creditLimit: Number(val('limit')) || 0, dueDay: Number(val('dueDay')) || 10, closingDay: Number(val('closingDay')) || 3 }); toast.success('Cartão adicionado.')
      } else if (modal === 'category') {
        if (!val('name')) throw new Error('Informe o nome da categoria.')
        await categoryDb.create({ userId: user.id, name: val('name'), transactionType: val('type'), color: val('color') }); toast.success('Categoria criada.')
      } else if (modal === 'budget') {
        if (Number(val('limit')) <= 0) throw new Error('Informe um limite mensal maior que zero.')
        await budgetDb.create({ userId: user.id, month: val('month'), categoryId: val('category') || null, limitAmount: Number(val('limit')) }); toast.success('Orçamento criado.')
      } else if (modal === 'goal') {
        if (!val('name') || Number(val('target')) <= 0) throw new Error('Informe o nome e o valor desejado para a meta.')
        await goalDb.create({ userId: user.id, name: val('name'), targetAmount: Number(val('target')), currentAmount: Number(val('current')) || 0, dueDate: val('dueDate') || null }); toast.success('Meta criada.')
      } else if (modal === 'contribution') {
        const goal = goals.find((item) => item.id === goalId)
        if (!goal || Number(val('amount')) <= 0) throw new Error('Informe um valor para adicionar à meta.')
        await goalDb.update(goal.id, { currentAmount: Number(goal.currentAmount) + Number(val('amount')) }); toast.success('Progresso atualizado.')
      }
      setModal(null); await refresh(user.id)
    } catch (error) { toast.error(error instanceof Error ? error.message : 'Não foi possível salvar. Tente novamente.') }
  }

  const remove = async (id: string) => {
    if (!user || !window.confirm('Excluir esta movimentação?')) return
    try { await txDb.delete(id); toast.success('Movimentação excluída.'); await refresh(user.id) }
    catch (error) { toast.error(error instanceof Error ? error.message : 'Não foi possível excluir.') }
  }
  const exportExcel = () => {
    const rows = filtered.map((row) => ({ Data: row.transactionDate, Descrição: row.title, Tipo: row.transactionType === 'income' ? 'Receita' : 'Despesa', Categoria: categories.find((c) => c.id === row.categoryId)?.name ?? 'Sem categoria', Valor: Number(row.amount), Conta: accounts.find((a) => a.id === row.accountId)?.name ?? '', Cartão: cards.find((c) => c.id === row.cardId)?.name ?? '', Observação: row.note ?? '', Parcela: `${row.installmentIndex}/${row.installmentCount}` }))
    const workbook = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(rows), 'Movimentações')
    XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(accounts.map((a) => ({ Nome: a.name, Tipo: accountName(a.accountType), SaldoInicial: Number(a.initialBalance) }))), 'Contas')
    XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(cards.map((c) => ({ Nome: c.name, Final: c.lastFour, Limite: Number(c.creditLimit), Fechamento: c.closingDay, Vencimento: c.dueDay }))), 'Cartões')
    XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(categories.map((c) => ({ Nome: c.name, Tipo: c.transactionType === 'income' ? 'Receita' : 'Despesa', Cor: c.color }))), 'Categorias')
    XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(budgets.map((b) => ({ Mês: b.month, Categoria: categories.find((c) => c.id === b.categoryId)?.name ?? 'Todas as despesas', Limite: Number(b.limitAmount) }))), 'Orçamentos')
    XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(goals.map((g) => ({ Meta: g.name, Objetivo: Number(g.targetAmount), Atual: Number(g.currentAmount), Prazo: g.dueDate ?? '' }))), 'Metas')
    XLSX.writeFile(workbook, `financex-dados-${month}.xlsx`); toast.success('Arquivo Excel exportado com seus dados financeiros.')
  }
  const exportBackup = () => {
    const backup = { product: 'FinanceX', formatVersion: 1, exportedAt: new Date().toISOString(), transactions: tx, accounts, cards, categories, budgets, goals }
    const url = URL.createObjectURL(new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' }))
    const link = document.createElement('a'); link.href = url; link.download = `financex-backup-${month}.json`; link.click(); URL.revokeObjectURL(url)
    toast.success('Backup completo baixado neste dispositivo.')
  }
  const exportPdf = () => {
    const pdf = new jsPDF(); pdf.setFont('helvetica', 'bold'); pdf.setFontSize(19); pdf.text('FinanceX · Relatório financeiro', 16, 20); pdf.setFont('helvetica', 'normal'); pdf.setFontSize(10); pdf.text(`Período ${month} · Receitas ${currency(income)} · Despesas ${currency(expenses)}`, 16, 29)
    let y = 42
    filtered.forEach((row) => { const cat = categories.find((c) => c.id === row.categoryId)?.name ?? 'Sem categoria'; const lines = pdf.splitTextToSize(`${dateLabel(row.transactionDate)} · ${row.transactionType === 'income' ? 'Receita' : 'Despesa'} · ${row.title} · ${cat} · ${currency(Number(row.amount))}`, 175); if (y + lines.length * 6 > 280) { pdf.addPage(); y = 20 } pdf.text(lines, 16, y); y += lines.length * 6 + 3 })
    pdf.save(`financex-relatorio-${month}.pdf`); toast.success('Relatório em PDF exportado.')
  }
  const toggleTheme = () => { const next = !dark; setDark(next); document.documentElement.classList.toggle('dark', next); localStorage.setItem('financex-theme', next ? 'dark' : 'light') }
  const installApp = async () => { if (!install) { setShowInstallHelp(true); return } await install.prompt(); await install.userChoice; setInstall(null) }

  if (authLoading) return <Loading />
  if (!user) return <SignIn />
  if (busy && !tx.length && !accounts.length) return <Loading />
  const title = nav.find((item) => item.id === page)?.label ?? 'FinanceX'
  const currentGoal = goals.find((item) => item.id === goalId)

  return <div className="min-h-dvh bg-background text-foreground">
    <aside className="fixed inset-y-0 left-0 z-20 hidden w-[258px] flex-col border-r border-border/80 bg-sidebar px-5 py-6 lg:flex"><Brand /><p className="mb-3 mt-10 px-3 text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground">Seu dinheiro, com clareza</p><nav className="flex-1 space-y-1" aria-label="Navegação principal">{nav.map((item) => <Nav key={item.id} item={item} active={page === item.id} onClick={() => setPage(item.id)} />)}</nav><div className="rounded-2xl border border-border/80 bg-background/70 p-4"><div className="flex items-center gap-2 text-xs font-semibold"><Check className="h-4 w-4 text-primary" /> Seus dados são privados</div><p className="mt-2 text-[11px] leading-relaxed text-muted-foreground">Cada conta visualiza apenas as próprias movimentações.</p></div><div className="mt-4 flex items-center gap-2 border-t border-border pt-4"><div className="grid h-9 w-9 place-items-center rounded-xl bg-primary/10 text-sm font-bold text-primary">{(user.displayName ?? user.email ?? 'F').charAt(0).toUpperCase()}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold">{user.displayName || 'Minha conta'}</p><p className="truncate text-[10px] text-muted-foreground">{user.email}</p></div><button onClick={() => void blink.auth.logout()} aria-label="Sair da conta" className="rounded-lg p-2 text-muted-foreground hover:bg-muted"><LogOut className="h-4 w-4" /></button></div></aside>
    <div className="lg:pl-[258px]"><header className="sticky top-0 z-10 flex h-[72px] items-center justify-between border-b border-border/70 bg-background/90 px-4 backdrop-blur-xl sm:px-7 lg:px-10"><div className="lg:hidden"><Brand compact /></div><div className="hidden lg:block"><p className="text-xs text-muted-foreground">{new Date().toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'long' })}</p><p className="mt-0.5 text-sm font-semibold">{title}</p></div><div className="flex items-center gap-2"><button onClick={installApp} className="hidden items-center gap-2 rounded-xl border border-border px-3 py-2 text-xs font-semibold hover:bg-muted sm:flex"><Smartphone className="h-4 w-4 text-primary" /> Instalar app</button><button onClick={toggleTheme} aria-label={dark ? 'Ativar modo claro' : 'Ativar modo escuro'} className="rounded-xl border border-border p-2.5 text-muted-foreground hover:bg-muted">{dark ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}</button><button onClick={() => setModal('transaction')} className="flex h-10 items-center gap-2 rounded-xl bg-primary px-3.5 text-xs font-bold text-primary-foreground shadow-sm transition hover:scale-[1.02] active:scale-[0.98] sm:px-4 sm:text-sm"><Plus className="h-4 w-4" /><span className="hidden sm:inline">Novo lançamento</span><span className="sm:hidden">Novo</span></button></div></header>
      <main className="mx-auto max-w-[1440px] px-4 pb-28 pt-7 sm:px-7 lg:px-10 lg:pb-10 lg:pt-9"><div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[0.18em] text-primary">{monthLabel(month)}</p><h1 className="mt-2 font-serif text-3xl font-medium tracking-tight sm:text-4xl">{page === 'overview' ? `Olá${user.displayName ? `, ${user.displayName.split(' ')[0]}` : ''}.` : title}</h1><p className="mt-2 max-w-xl text-sm text-muted-foreground">{page === 'overview' ? 'Uma visão tranquila e completa do seu dinheiro.' : page === 'transactions' ? 'Encontre, revise e organize cada movimentação.' : page === 'accounts' ? 'Contas, carteiras e cartões em um só lugar.' : page === 'planning' ? 'Pequenos planos hoje, mais liberdade amanhã.' : 'Acompanhe seus números e leve seus dados com você.'}</p></div><span className="hidden items-center gap-2 rounded-full border border-border bg-card px-3 py-2 text-xs text-muted-foreground sm:flex"><i className="h-2 w-2 rounded-full bg-primary" /> Atualizado agora</span></div>
        {page === 'overview' && <Overview rows={monthTx} balance={balance} income={income} expenses={expenses} chart={chart} breakdown={breakdown} categories={categories} go={setPage} />}
        {page === 'transactions' && <Transactions rows={filtered} categories={categories} search={search} setSearch={setSearch} kind={kindFilter} setKind={setKindFilter} cat={categoryFilter} setCat={setCategoryFilter} dateFrom={dateFrom} setDateFrom={setDateFrom} dateTo={dateTo} setDateTo={setDateTo} remove={remove} create={() => setModal('transaction')} />}
        {page === 'accounts' && <Accounts accounts={accounts} cards={cards} transactions={tx} month={month} addAccount={() => setModal('account')} addCard={() => setModal('card')} />}
        {page === 'planning' && <Planning budgets={budgets} goals={goals} categories={categories} tx={tx} month={month} addBudget={() => setModal('budget')} addGoal={() => setModal('goal')} addCategory={() => setModal('category')} contribute={(id) => { setGoalId(id); setModal('contribution') }} />}
        {page === 'reports' && <Reports chart={chart} rows={filtered} income={income} expenses={expenses} excel={exportExcel} pdf={exportPdf} backup={exportBackup} />}
      </main></div>
    <nav className="fixed inset-x-0 bottom-0 z-30 grid grid-cols-5 border-t border-border/80 bg-background/95 px-1 pb-[max(env(safe-area-inset-bottom),0.5rem)] pt-2 backdrop-blur-xl lg:hidden" aria-label="Navegação inferior">{nav.map((item) => <Nav key={item.id} item={item} active={page === item.id} onClick={() => setPage(item.id)} mobile />)}</nav>
    {modal && <RecordModal kind={modal} categories={categories} accounts={accounts} cards={cards} goal={currentGoal} close={() => setModal(null)} submit={submit} />}
    {showInstallHelp && <InstallHelp close={() => setShowInstallHelp(false)} />}
  </div>
}

function Overview({ rows, balance, income, expenses, chart, breakdown, categories, go }: { rows: FinanceTransactionsRow[]; balance: number; income: number; expenses: number; chart: { name: string; receitas: number; despesas: number }[]; breakdown: { name: string; value: number; color: string }[]; categories: FinanceCategoriesRow[]; go: (page: Page) => void }) {
  return <div className="space-y-5 animate-fade-in"><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Saldo nas contas" value={currency(balance)} note="Saldo inicial + movimentações" icon={Wallet} /><Metric label="Receitas do mês" value={currency(income)} note={`${rows.filter((r) => r.transactionType === 'income').length} lançamentos`} icon={ArrowDownLeft} /><Metric label="Despesas do mês" value={currency(expenses)} note={`${rows.filter((r) => r.transactionType === 'expense').length} lançamentos`} icon={ArrowUpRight} /><Metric label="Disponível no mês" value={currency(income - expenses)} note="Receitas menos despesas" icon={TrendingUp} /></section>
    <section className="grid gap-5 xl:grid-cols-[1.6fr_1fr]"><Panel title="Fluxo financeiro" description="Receitas e despesas dos últimos 6 meses"><div className="h-[260px] pt-3"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chart} margin={{ top: 8, right: 4, left: -18, bottom: 0 }}><defs><linearGradient id="incomeFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--color-primary)" stopOpacity={0.24} /><stop offset="95%" stopColor="var(--color-primary)" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="var(--color-border)" strokeDasharray="4 5" vertical={false} /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: 'var(--color-muted-foreground)', fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--color-muted-foreground)', fontSize: 10 }} tickFormatter={(v: number) => v >= 1000 ? `${v / 1000}k` : String(v)} /><Tooltip formatter={(value) => currency(Number(value))} /><Area type="monotone" dataKey="receitas" name="Receitas" stroke="var(--color-primary)" strokeWidth={2.5} fill="url(#incomeFill)" /><Area type="monotone" dataKey="despesas" name="Despesas" stroke="#c89b5f" strokeWidth={2} fill="#c89b5f" fillOpacity={0.1} /></AreaChart></ResponsiveContainer></div><div className="mt-2 flex gap-5 text-[11px] text-muted-foreground"><span>● Receitas</span><span className="text-[#c89b5f]">● Despesas</span></div></Panel>
      <Panel title="Despesas por categoria" description="Onde seu dinheiro foi neste mês">{breakdown.length ? <div className="flex flex-col items-center gap-2 sm:flex-row xl:flex-col 2xl:flex-row"><div className="h-[190px] w-[190px] shrink-0"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={breakdown} dataKey="value" nameKey="name" innerRadius={58} outerRadius={84} paddingAngle={3} stroke="none">{breakdown.map((item) => <Cell key={item.name} fill={item.color} />)}</Pie><Tooltip formatter={(v) => currency(Number(v))} /></PieChart></ResponsiveContainer></div><div className="w-full space-y-3">{breakdown.slice(0, 5).map((item) => <div key={item.name} className="flex items-center gap-2 text-xs"><i className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: item.color }} /><span className="flex-1 truncate text-muted-foreground">{item.name}</span><b>{currency(item.value)}</b></div>)}</div></div> : <Empty icon={BarChart3} title="Seu gráfico começa aqui" text="Registre despesas para acompanhar por categoria." />}</Panel></section>
    <Panel title="Movimentações recentes" description="Seus últimos registros" action={<button onClick={() => go('transactions')} className="text-xs font-semibold text-primary hover:underline">Ver todas</button>}>{rows.length ? <Rows rows={[...rows].sort((a, b) => b.transactionDate.localeCompare(a.transactionDate)).slice(0, 5)} categories={categories} /> : <Empty icon={Activity} title="Tudo começa com um lançamento" text="Adicione sua primeira receita ou despesa para dar vida ao painel." />}</Panel></div>
}

function Transactions({ rows, categories, search, setSearch, kind, setKind, cat, setCat, dateFrom, setDateFrom, dateTo, setDateTo, remove, create }: { rows: FinanceTransactionsRow[]; categories: FinanceCategoriesRow[]; search: string; setSearch: (v: string) => void; kind: string; setKind: (v: string) => void; cat: string; setCat: (v: string) => void; dateFrom: string; setDateFrom: (v: string) => void; dateTo: string; setDateTo: (v: string) => void; remove: (id: string) => void; create: () => void }) {
  return <Panel title="Todas as movimentações" description={`${rows.length} registros encontrados`} action={<Action onClick={create}>Adicionar</Action>}><div className="mb-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-[1fr_170px_190px_150px_150px]"><div className="relative sm:col-span-2 xl:col-span-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar descrição ou categoria" aria-label="Buscar" className={`${input} mt-0 pl-10`} /></div><select value={kind} onChange={(e) => setKind(e.target.value)} className={`${input} mt-0`} aria-label="Filtrar por tipo"><option value="all">Todos os tipos</option><option value="income">Receitas</option><option value="expense">Despesas</option></select><select value={cat} onChange={(e) => setCat(e.target.value)} className={`${input} mt-0`} aria-label="Filtrar categoria"><option value="all">Todas as categorias</option>{categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select><input value={dateFrom} onChange={(e) => setDateFrom(e.target.value)} type="date" aria-label="Data inicial" className={`${input} mt-0`} /><input value={dateTo} onChange={(e) => setDateTo(e.target.value)} type="date" aria-label="Data final" className={`${input} mt-0`} /></div>{rows.length ? <Rows rows={rows} categories={categories} remove={remove} /> : <Empty icon={Filter} title="Nenhum resultado encontrado" text="Tente mudar os filtros ou registre uma movimentação." />}</Panel>
}

function Accounts({ accounts, cards, transactions, month, addAccount, addCard }: { accounts: FinanceAccountsRow[]; cards: FinanceCardsRow[]; transactions: FinanceTransactionsRow[]; month: string; addAccount: () => void; addCard: () => void }) {
  return <div className="space-y-5"><Panel title="Contas e carteiras" description="Saldo inicial ajustado pelos seus lançamentos" action={<Action onClick={addAccount}>Nova conta</Action>}>{accounts.length ? <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{accounts.map((account) => { const list = transactions.filter((r) => r.accountId === account.id); const amount = Number(account.initialBalance) + list.reduce((sum, r) => sum + (r.transactionType === 'income' ? 1 : -1) * Number(r.amount), 0); return <div key={account.id} className="rounded-2xl border border-border bg-background p-4 transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex justify-between"><span className="grid h-10 w-10 place-items-center rounded-xl bg-primary/10 text-primary"><Landmark className="h-5 w-5" /></span><small className="rounded-full bg-muted px-2.5 py-1 text-muted-foreground">{accountName(account.accountType)}</small></div><p className="mt-5 text-sm font-semibold">{account.name}</p><p className="mt-1 font-serif text-2xl">{currency(amount)}</p><p className="mt-1 text-[11px] text-muted-foreground">{list.length} movimentações vinculadas</p></div> })}</div> : <Empty icon={Landmark} title="Adicione sua primeira conta" text="Cadastre bancos, carteiras ou dinheiro em espécie." action={addAccount} actionText="Adicionar conta" />}</Panel>
    <Panel title="Cartões e faturas" description="Faturas estimadas com base nas compras registradas manualmente" action={<Action outline onClick={addCard}>Novo cartão</Action>}>{cards.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{cards.map((card) => { const spent = transactions.filter((r) => r.cardId === card.id && r.transactionDate.slice(0, 7) === month && r.transactionType === 'expense').reduce((sum, r) => sum + Number(r.amount), 0); const ratio = Number(card.creditLimit) ? Math.min(100, spent / Number(card.creditLimit) * 100) : 0; return <div key={card.id} className="overflow-hidden rounded-2xl border border-border bg-card"><div className="bg-primary p-5 text-primary-foreground"><div className="flex justify-between"><CreditCard className="h-5 w-5" /><span>•••• {card.lastFour}</span></div><p className="mt-7 text-sm font-semibold">{card.name}</p><p className="mt-1 text-[10px] opacity-75">Fecha dia {card.closingDay} · vence dia {card.dueDay}</p></div><div className="p-4"><p className="text-[10px] text-muted-foreground">Fatura parcial · {monthLabel(month)}</p><div className="mt-1 flex items-end justify-between"><b className="text-xl">{currency(spent)}</b><small className="text-muted-foreground">Limite {currency(Number(card.creditLimit))}</small></div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${ratio}%` }} /></div><p className="mt-2 text-[10px] text-muted-foreground">Compras parceladas aparecem nas faturas futuras.</p></div></div> })}</div> : <Empty icon={CreditCard} title="Nenhum cartão cadastrado" text="Adicione seu cartão para acompanhar parcelas e faturas." action={addCard} actionText="Adicionar cartão" />}</Panel></div>
}

function Planning({ budgets, goals, categories, tx, month, addBudget, addGoal, addCategory, contribute }: { budgets: FinanceBudgetsRow[]; goals: FinanceGoalsRow[]; categories: FinanceCategoriesRow[]; tx: FinanceTransactionsRow[]; month: string; addBudget: () => void; addGoal: () => void; addCategory: () => void; contribute: (id: string) => void }) {
  const monthly = budgets.filter((budget) => budget.month === month)
  return <div className="space-y-5"><Panel title="Orçamentos mensais" description="Compare os limites com as despesas registradas" action={<Action onClick={addBudget}>Novo orçamento</Action>}>{monthly.length ? <div className="grid gap-3 md:grid-cols-2">{monthly.map((budget) => { const used = tx.filter((r) => r.transactionDate.slice(0, 7) === month && r.transactionType === 'expense' && (!budget.categoryId || r.categoryId === budget.categoryId)).reduce((sum, r) => sum + Number(r.amount), 0); const limit = Number(budget.limitAmount); const percent = limit ? Math.min(100, used / limit * 100) : 0; return <div key={budget.id} className="rounded-2xl border border-border bg-background p-4"><div className="flex justify-between"><div><b className="text-sm">{categories.find((c) => c.id === budget.categoryId)?.name ?? 'Todas as despesas'}</b><p className="mt-1 text-[11px] text-muted-foreground">{monthLabel(budget.month)}</p></div><span className={`rounded-full px-2.5 py-1 text-[10px] font-semibold ${percent >= 100 ? 'bg-destructive/10 text-destructive' : 'bg-secondary text-secondary-foreground'}`}>{Math.round(percent)}%</span></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${percent >= 100 ? 'bg-destructive' : 'bg-primary'}`} style={{ width: `${percent}%` }} /></div><div className="mt-2 flex justify-between text-[11px]"><b>{currency(used)} <small className="font-normal text-muted-foreground">usados</small></b><span className="text-muted-foreground">de {currency(limit)}</span></div></div> })}</div> : <Empty icon={CalendarDays} title="Dê um limite ao seu mês" text="Crie orçamentos por categoria e acompanhe o ritmo dos gastos." action={addBudget} actionText="Criar orçamento" />}</Panel>
    <Panel title="Metas financeiras" description="Acompanhe o progresso dos seus planos" action={<Action outline onClick={addGoal}>Nova meta</Action>}>{goals.length ? <div className="grid gap-3 md:grid-cols-2">{goals.map((goal) => { const target = Number(goal.targetAmount); const current = Number(goal.currentAmount); const percent = target ? Math.min(100, current / target * 100) : 0; return <div key={goal.id} className="rounded-2xl border border-border bg-background p-4"><div className="flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-xl bg-accent/60 text-accent-foreground"><Goal className="h-5 w-5" /></span><button onClick={() => contribute(goal.id)} className="rounded-lg border border-border px-3 py-2 text-[11px] font-semibold hover:bg-muted">Adicionar valor</button></div><b className="mt-4 block text-sm">{goal.name}</b><div className="mt-1 flex items-baseline justify-between"><span className="font-serif text-xl">{currency(current)}</span><small className="text-muted-foreground">de {currency(target)}</small></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${percent}%` }} /></div><p className="mt-2 text-[10px] text-muted-foreground">{Math.round(percent)}% concluído{goal.dueDate ? ` · até ${dateLabel(goal.dueDate)}` : ''}</p></div> })}</div> : <Empty icon={Goal} title="Qual é o seu próximo plano?" text="Crie uma meta e acompanhe cada contribuição." action={addGoal} actionText="Criar meta" />}</Panel>
    <Panel title="Categorias personalizadas" description="Organize os lançamentos do seu jeito" action={<Action outline onClick={addCategory}>Nova categoria</Action>}><div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{categories.map((category) => <div key={category.id} className="flex items-center gap-3 rounded-xl border border-border/80 bg-background px-3 py-3"><i className="h-3 w-3 rounded-full" style={{ backgroundColor: category.color }} /><b className="flex-1 text-xs">{category.name}</b><small className="rounded-full bg-muted px-2 py-1 text-muted-foreground">{category.transactionType === 'income' ? 'Receita' : 'Despesa'}</small></div>)}</div></Panel></div>
}

function Reports({ chart, rows, income, expenses, excel, pdf, backup }: { chart: { name: string; receitas: number; despesas: number }[]; rows: FinanceTransactionsRow[]; income: number; expenses: number; excel: () => void; pdf: () => void; backup: () => void }) {
  return <Panel title="Relatório do período" description="Resumo calculado dos lançamentos salvos" action={<div className="flex flex-wrap gap-2"><button onClick={backup} className="flex items-center gap-2 rounded-xl border border-border px-3 py-2 text-xs font-semibold hover:bg-muted"><Download className="h-4 w-4" />Backup JSON</button><button onClick={pdf} className="flex items-center gap-2 rounded-xl border border-border px-3 py-2 text-xs font-semibold hover:bg-muted"><Download className="h-4 w-4" />PDF</button><button onClick={excel} className="flex items-center gap-2 rounded-xl bg-primary px-3 py-2 text-xs font-bold text-primary-foreground"><FileSpreadsheet className="h-4 w-4" />Excel</button></div>}><div className="grid gap-3 sm:grid-cols-3"><Summary label="Receitas do mês" amount={income} /><Summary label="Despesas do mês" amount={expenses} /><Summary label="Resultado do mês" amount={income - expenses} highlight /></div><div className="mt-6 h-[300px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chart} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}><CartesianGrid stroke="var(--color-border)" strokeDasharray="4 5" vertical={false} /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: 'var(--color-muted-foreground)', fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--color-muted-foreground)', fontSize: 10 }} /><Tooltip formatter={(v) => currency(Number(v))} /><Area type="monotone" dataKey="receitas" name="Receitas" stroke="var(--color-primary)" fill="var(--color-primary)" fillOpacity={0.1} /><Area type="monotone" dataKey="despesas" name="Despesas" stroke="#c89b5f" fill="#c89b5f" fillOpacity={0.08} /></AreaChart></ResponsiveContainer></div><p className="mt-3 text-xs text-muted-foreground">Excel inclui movimentações filtradas e abas de contas, cartões, categorias, orçamentos e metas. O backup JSON reúne todos os seus registros para guarda local.</p><p className="mt-2 text-[11px] text-muted-foreground">O PDF contém o resumo mensal e {rows.length} movimentações selecionadas.</p></Panel>
}

function RecordModal({ kind, categories, accounts, cards, goal, close, submit }: { kind: ModalKind; categories: FinanceCategoriesRow[]; accounts: FinanceAccountsRow[]; cards: FinanceCardsRow[]; goal?: FinanceGoalsRow; close: () => void; submit: (event: FormEvent<HTMLFormElement>) => void }) {
  const headings: Record<ModalKind, string> = { transaction: 'Novo lançamento', account: 'Adicionar conta', card: 'Adicionar cartão', budget: 'Criar orçamento', goal: 'Criar meta financeira', category: 'Nova categoria', contribution: `Adicionar à meta${goal ? ` · ${goal.name}` : ''}` }
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-foreground/35 p-0 backdrop-blur-sm sm:items-center sm:p-4" onMouseDown={(e) => { if (e.target === e.currentTarget) close() }}><section role="dialog" aria-modal="true" aria-labelledby="modal-title" className="max-h-[92dvh] w-full overflow-y-auto rounded-t-[28px] border border-border bg-card p-5 shadow-2xl sm:max-w-lg sm:rounded-[28px] sm:p-6"><div className="mb-5 flex items-center justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-primary">FinanceX</p><h2 id="modal-title" className="mt-1 font-serif text-2xl">{headings[kind]}</h2></div><button onClick={close} aria-label="Fechar" className="rounded-xl p-2 text-muted-foreground hover:bg-muted"><X className="h-5 w-5" /></button></div><form key={kind} onSubmit={submit} className="space-y-4">
    {kind === 'transaction' && <><div className="grid grid-cols-2 gap-2 rounded-xl bg-muted p-1">{[['expense', 'Despesa'], ['income', 'Receita']].map(([value, text], i) => <label key={value} className="cursor-pointer"><input type="radio" name="type" value={value} defaultChecked={i === 0} className="peer sr-only" /><span className="block rounded-lg py-2.5 text-center text-xs font-semibold text-muted-foreground peer-checked:bg-card peer-checked:text-foreground peer-checked:shadow-sm">{text}</span></label>)}</div><div className="grid gap-4 sm:grid-cols-2"><Field title="Descrição"><input name="title" required placeholder="Ex.: Mercado da semana" className={input} /></Field><Field title="Valor total"><input name="amount" type="number" min="0.01" step="0.01" required placeholder="0,00" className={input} /></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field title="Data"><input name="date" type="date" defaultValue={dateKey(new Date())} required className={input} /></Field><Field title="Categoria"><select name="category" defaultValue="" className={input}><option value="">Sem categoria</option>{categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field title="Conta ou carteira"><select name="account" className={input}><option value="">Não vincular</option>{accounts.map((a) => <option key={a.id} value={a.id}>{a.name}</option>)}</select></Field><Field title="Cartão de crédito"><select name="card" className={input}><option value="">Não vincular</option>{cards.map((c) => <option key={c.id} value={c.id}>{c.name} ·•••• {c.lastFour}</option>)}</select></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field title="Forma de pagamento"><select name="payment" className={input}><option value="">Não informada</option>{[['pix','Pix'],['debit','Débito'],['credit','Crédito'],['cash','Dinheiro'],['transfer','Transferência'],['other','Outra']].map(([v,t]) => <option key={v} value={v}>{t}</option>)}</select></Field><Field title="Parcelas"><select name="installments" className={input}>{[1,2,3,4,6,10,12,18,24].map((n) => <option key={n} value={n}>{n === 1 ? 'À vista' : `${n}x`}</option>)}</select></Field></div><Field title="Observação"><input name="note" placeholder="Opcional" className={input} /></Field><p className="rounded-xl bg-secondary/60 px-3 py-2.5 text-[10px] leading-relaxed text-secondary-foreground">O valor total é dividido igualmente entre as parcelas e os meses seguintes.</p></>}
    {kind === 'account' && <><Field title="Nome da conta"><input name="name" required placeholder="Ex.: Conta principal" className={input} /></Field><div className="grid grid-cols-2 gap-4"><Field title="Tipo"><select name="accountType" className={input}><option value="checking">Conta corrente</option><option value="savings">Poupança</option><option value="cash">Carteira / dinheiro</option><option value="investment">Investimentos</option></select></Field><Field title="Saldo inicial"><input name="balance" type="number" step="0.01" defaultValue="0" className={input} /></Field></div></>}
    {kind === 'card' && <><Field title="Nome do cartão"><input name="name" required placeholder="Ex.: Cartão principal" className={input} /></Field><div className="grid grid-cols-2 gap-4"><Field title="Quatro últimos dígitos"><input name="lastFour" maxLength={4} required inputMode="numeric" placeholder="1234" className={input} /></Field><Field title="Limite total"><input name="limit" type="number" min="0" step="0.01" defaultValue="0" className={input} /></Field></div><div className="grid grid-cols-2 gap-4"><Field title="Dia de fechamento"><input name="closingDay" type="number" min="1" max="31" defaultValue="3" className={input} /></Field><Field title="Dia de vencimento"><input name="dueDay" type="number" min="1" max="31" defaultValue="10" className={input} /></Field></div></>}
    {kind === 'category' && <><Field title="Nome da categoria"><input name="name" required placeholder="Ex.: Educação" className={input} /></Field><div className="grid grid-cols-2 gap-4"><Field title="Tipo"><select name="type" className={input}><option value="expense">Despesa</option><option value="income">Receita</option></select></Field><Field title="Cor"><select name="color" className={input}>{[['#6f9e8a','Sálvia'],['#c89b5f','Âmbar'],['#7495aa','Azul mineral'],['#a97774','Terracota'],['#aa8d72','Areia'],['#668eb0','Azul profundo']].map(([v,t]) => <option key={v} value={v}>{t}</option>)}</select></Field></div></>}
    {kind === 'budget' && <><Field title="Categoria"><select name="category" className={input}><option value="">Todas as despesas</option>{categories.filter((c) => c.transactionType === 'expense').map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><div className="grid grid-cols-2 gap-4"><Field title="Mês"><input name="month" type="month" defaultValue={monthKey()} required className={input} /></Field><Field title="Limite mensal"><input name="limit" type="number" min="0.01" step="0.01" required placeholder="0,00" className={input} /></Field></div></>}
    {kind === 'goal' && <><Field title="Nome da meta"><input name="name" required placeholder="Ex.: Viagem de férias" className={input} /></Field><div className="grid grid-cols-2 gap-4"><Field title="Valor desejado"><input name="target" type="number" min="0.01" step="0.01" required placeholder="0,00" className={input} /></Field><Field title="Já economizei"><input name="current" type="number" min="0" step="0.01" defaultValue="0" className={input} /></Field></div><Field title="Data desejada"><input name="dueDate" type="date" className={input} /></Field></>}
    {kind === 'contribution' && <><p className="text-xs text-muted-foreground">Progresso atual: {currency(Number(goal?.currentAmount ?? 0))} de {currency(Number(goal?.targetAmount ?? 0))}.</p><Field title="Valor a adicionar"><input name="amount" type="number" min="0.01" step="0.01" required placeholder="0,00" className={input} /></Field></>}
    <div className="flex gap-3 pt-2"><button type="button" onClick={close} className="h-11 flex-1 rounded-xl border border-border text-sm font-semibold hover:bg-muted">Cancelar</button><button type="submit" className="h-11 flex-1 rounded-xl bg-primary text-sm font-bold text-primary-foreground shadow-sm transition hover:scale-[1.01] active:scale-[0.99]">Salvar</button></div>
  </form></section></div>
}

function SignIn() { return <main className="grid min-h-dvh bg-background lg:grid-cols-[1fr_.85fr]"><section className="flex flex-col justify-between p-6 sm:p-10"><Brand /><div className="mx-auto my-12 w-full max-w-md"><p className="text-xs font-bold uppercase tracking-[0.2em] text-primary">Seu dinheiro, no seu ritmo</p><h1 className="mt-4 font-serif text-4xl leading-tight sm:text-5xl">Mais clareza para escolher o que vem depois.</h1><p className="mt-4 text-sm leading-relaxed text-muted-foreground">Registre movimentações manualmente, acompanhe seus planos e mantenha cada detalhe financeiro só seu.</p><button onClick={() => blink.auth.login(window.location.href)} className="mt-8 flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-primary px-5 text-sm font-bold text-primary-foreground shadow-md transition hover:scale-[1.01]">Entrar ou criar minha conta <ArrowUpRight className="h-4 w-4" /></button><p className="mt-4 text-center text-[11px] text-muted-foreground">Na entrada segura, escolha “Criar conta” para começar.</p><div className="mt-6 flex gap-2 rounded-xl border border-border bg-card p-3 text-[11px] text-muted-foreground"><Check className="h-4 w-4 shrink-0 text-primary" /> A validação de compras pela Hotmart ainda não está conectada.</div></div><p className="text-[10px] text-muted-foreground">FinanceX · Finanças exclusivamente manuais</p></section><section className="relative hidden overflow-hidden bg-primary p-12 text-primary-foreground lg:flex lg:flex-col lg:justify-between"><div className="absolute -right-28 -top-24 h-[420px] w-[420px] rounded-full border border-primary-foreground/15" /><div className="absolute -right-10 top-8 h-[270px] w-[270px] rounded-full border border-primary-foreground/15" /><div className="relative mt-24 max-w-lg"><p className="text-xs font-semibold uppercase tracking-[0.2em] opacity-70">Um olhar mais leve</p><p className="mt-5 font-serif text-5xl leading-tight">Suas escolhas de hoje constroem espaço para amanhã.</p></div><div className="relative grid grid-cols-2 gap-3"><div className="rounded-2xl border border-primary-foreground/15 bg-primary-foreground/10 p-4"><p className="text-xs opacity-70">Movimentações</p><p className="mt-2 text-sm font-semibold">Feitas por você</p></div><div className="rounded-2xl border border-primary-foreground/15 bg-primary-foreground/10 p-4"><p className="text-xs opacity-70">Privacidade</p><p className="mt-2 text-sm font-semibold">Seus dados, só seus</p></div></div></section></main> }
function Loading() { return <div className="grid min-h-dvh place-items-center bg-background"><div className="flex flex-col items-center gap-3"><div className="h-9 w-9 animate-spin rounded-full border-[3px] border-primary/20 border-t-primary" /><span className="text-xs text-muted-foreground">Preparando suas finanças…</span></div></div> }
function InstallHelp({ close }: { close: () => void }) { return <div className="fixed inset-0 z-50 grid place-items-center bg-foreground/35 p-4 backdrop-blur-sm"><section role="dialog" aria-modal="true" className="w-full max-w-sm rounded-3xl border border-border bg-card p-6 shadow-2xl"><button onClick={close} aria-label="Fechar" className="float-right rounded-lg p-1 text-muted-foreground hover:bg-muted"><X className="h-4 w-4" /></button><Smartphone className="h-6 w-6 text-primary" /><h2 className="mt-4 font-serif text-2xl">Leve o FinanceX com você</h2><p className="mt-2 text-sm leading-relaxed text-muted-foreground">No iPhone, abra Compartilhar no Safari e escolha <b className="text-foreground">Adicionar à Tela de Início</b>. No Android, use o menu do navegador e toque em <b className="text-foreground">Instalar app</b> ou <b className="text-foreground">Adicionar à tela inicial</b>.</p><button onClick={close} className="mt-5 h-11 w-full rounded-xl bg-primary text-sm font-bold text-primary-foreground">Entendi</button></section></div> }
function Brand({ compact = false }: { compact?: boolean }) { return <div className="flex items-center gap-3"><img src="/financex-icon.svg" alt="" className={compact ? 'h-9 w-9 rounded-xl' : 'h-10 w-10 rounded-xl'} /><div><p className="font-serif text-lg font-semibold tracking-tight">FinanceX</p>{!compact && <p className="text-[10px] tracking-wide text-muted-foreground">FINANÇAS COM INTENÇÃO</p>}</div></div> }
function Nav({ item, active, onClick, mobile = false }: { item: { id: Page; label: string; icon: LucideIcon }; active: boolean; onClick: () => void; mobile?: boolean }) { const Icon = item.icon; return mobile ? <button onClick={onClick} aria-current={active ? 'page' : undefined} className={`flex min-w-0 flex-col items-center justify-center gap-1 rounded-xl py-1 text-[9px] font-semibold ${active ? 'text-primary' : 'text-muted-foreground'}`}><span className={`grid h-8 w-10 place-items-center rounded-xl ${active ? 'bg-primary/10' : ''}`}><Icon className="h-[18px] w-[18px]" /></span><span className="max-w-full truncate">{item.label === 'Lançamentos' ? 'Lançam.' : item.label === 'Planejamento' ? 'Planos' : item.label}</span></button> : <button onClick={onClick} aria-current={active ? 'page' : undefined} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-medium ${active ? 'bg-primary text-primary-foreground shadow-sm' : 'text-muted-foreground hover:bg-background hover:text-foreground'}`}><Icon className="h-[18px] w-[18px]" /><span>{item.label}</span>{active && <i className="ml-auto h-1.5 w-1.5 rounded-full bg-primary-foreground" />}</button> }
function Panel({ title, description, action, children }: { title: string; description?: string; action?: ReactNode; children: ReactNode }) { return <section className="rounded-2xl border border-border/80 bg-card p-4 shadow-sm sm:p-5"><div className="mb-5 flex items-start justify-between gap-3"><div><h2 className="text-sm font-semibold tracking-tight">{title}</h2>{description && <p className="mt-1 text-[11px] text-muted-foreground">{description}</p>}</div>{action}</div>{children}</section> }
function Metric({ label: name, value, note, icon: Icon }: { label: string; value: string; note: string; icon: LucideIcon }) { return <div className="rounded-2xl border border-border/80 bg-card p-4 shadow-sm transition hover:-translate-y-0.5 hover:shadow-md sm:p-5"><div className="flex items-center justify-between"><p className="text-xs font-medium text-muted-foreground">{name}</p><span className="grid h-9 w-9 place-items-center rounded-xl bg-primary/10 text-primary"><Icon className="h-4 w-4" /></span></div><p className="mt-5 font-serif text-[1.7rem] leading-none tracking-tight sm:text-[1.9rem]">{value}</p><p className="mt-2 text-[10px] text-muted-foreground">{note}</p></div> }
function Rows({ rows, categories, remove }: { rows: FinanceTransactionsRow[]; categories: FinanceCategoriesRow[]; remove?: (id: string) => void }) { return <div className="divide-y divide-border/70">{rows.map((row) => { const isIncome = row.transactionType === 'income'; const category = categories.find((c) => c.id === row.categoryId)?.name ?? 'Sem categoria'; return <div key={row.id} className="group flex items-center gap-3 py-3.5 first:pt-0 last:pb-0"><span className={`grid h-10 w-10 shrink-0 place-items-center rounded-xl ${isIncome ? 'bg-primary/10 text-primary' : 'bg-accent/35 text-accent-foreground'}`}>{isIncome ? <ArrowDownLeft className="h-4 w-4" /> : <ArrowUpRight className="h-4 w-4" />}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{row.title}</p><p className="mt-1 truncate text-[10px] text-muted-foreground">{category} · {dateLabel(row.transactionDate)}{Number(row.installmentCount) > 1 ? ` · Parcela ${row.installmentIndex}/${row.installmentCount}` : ''}</p></div><p className={`text-right text-sm font-semibold tabular-nums ${isIncome ? 'text-primary' : 'text-foreground'}`}>{isIncome ? '+' : '−'} {currency(Number(row.amount))}</p>{remove && <button onClick={() => remove(row.id)} aria-label={`Excluir ${row.title}`} className="ml-1 rounded-lg p-2 text-muted-foreground opacity-0 hover:bg-destructive/10 hover:text-destructive group-hover:opacity-100 focus:opacity-100"><Trash2 className="h-4 w-4" /></button>}</div> })}</div> }
function Empty({ icon: Icon, title, text, action, actionText }: { icon: LucideIcon; title: string; text: string; action?: () => void; actionText?: string }) { return <div className="flex min-h-[170px] flex-col items-center justify-center px-5 py-8 text-center"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-primary/10 text-primary"><Icon className="h-5 w-5" /></span><b className="mt-4 text-sm">{title}</b><p className="mt-1 max-w-sm text-xs leading-relaxed text-muted-foreground">{text}</p>{action && <button onClick={action} className="mt-4 rounded-xl bg-primary px-4 py-2.5 text-xs font-semibold text-primary-foreground">{actionText ?? 'Começar'}</button>}</div> }
function Action({ children, onClick, outline = false }: { children: ReactNode; onClick: () => void; outline?: boolean }) { return <button onClick={onClick} className={`flex items-center gap-2 rounded-xl px-3 py-2 text-xs font-bold ${outline ? 'border border-border hover:bg-muted' : 'bg-primary text-primary-foreground'}`}><Plus className="h-4 w-4" />{children}</button> }
function Field({ title, children }: { title: string; children: ReactNode }) { return <label className={label}>{title}{children}</label> }
function Summary({ label: title, amount, highlight = false }: { label: string; amount: number; highlight?: boolean }) { return <div className={`rounded-xl p-4 ${highlight ? 'bg-primary/10' : 'bg-muted/70'}`}><p className={`text-[10px] font-semibold uppercase tracking-wider ${highlight ? 'text-primary' : 'text-muted-foreground'}`}>{title}</p><p className={`mt-2 text-xl font-semibold ${highlight ? 'text-primary' : ''}`}>{currency(amount)}</p></div> }
function accountName(type: string) { return ({ checking: 'Conta corrente', savings: 'Poupança', cash: 'Carteira', investment: 'Investimentos' } as Record<string, string>)[type] ?? type }
function monthKey(date = new Date()) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}` }
function dateKey(date: Date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}` }
function addMonths(source: Date, count: number) { const date = new Date(source); const day = date.getDate(); date.setDate(1); date.setMonth(date.getMonth() + count); date.setDate(Math.min(day, new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate())); return date }
function currency(amount: number) { return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number.isFinite(amount) ? amount : 0) }
function dateLabel(date: string) { return new Date(`${date.slice(0, 10)}T12:00:00`).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' }).replace('.', '') }
function monthLabel(month: string) { const [year, n] = month.split('-').map(Number); return new Date(year, n - 1, 1).toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' }) }
